Lemma cells0_raw : forall ps, nth_error (CC.cp_PSS G.cp0) 0 = Some ps -> has_tag (SR.ps_cells ps) 1 = true.
Proof.
  intros ps H.
  assert (X : match nth_error (CC.cp_PSS G.cp0) 0 with Some p => has_tag (SR.ps_cells p) 1 | None => false end = true) by (vm_compute; reflexivity).
  rewrite H in X. exact X.
Qed.
Lemma cells0_esc : forall ps, nth_error (CC.cp_PSS G.cp0) 3 = Some ps ->
  (PB.has (SR.ps_cells ps) (NE 1) && PB.has (SR.ps_cells ps) (NE 2) && PB.has (SR.ps_cells ps) (NE 3))%bool = true.
Proof.
  intros ps H.
  assert (X : match nth_error (CC.cp_PSS G.cp0) 3 with
              | Some p => (PB.has (SR.ps_cells p) (NE 1) && PB.has (SR.ps_cells p) (NE 2) && PB.has (SR.ps_cells p) (NE 3))%bool
              | None => false end = true) by (vm_compute; reflexivity).
  rewrite H in X. exact X.
Qed.
Lemma dmax_raw : forall bs, quotes (EvStr 1 bs) + pay_hi (EvStr 1 bs) = 2 + len bs.
Proof. intros bs. reflexivity. Qed.
Lemma dmax_big : forall tag bs, tag = 2 \/ tag = 3 -> quotes (EvStr tag bs) + pay_hi (EvStr tag bs) = len bs.
Proof. intros tag bs [-> | ->]; reflexivity. Qed.
Lemma dmax_esc : forall tag bs, tag <> 1 -> tag <> 2 -> tag <> 3 ->
  quotes (EvStr tag bs) + pay_hi (EvStr tag bs) = 2 + esc_len bs /\ pay_ok (EvStr tag bs) (esc_len bs) /\ quotes (EvStr tag bs) = 2.
Proof.
  intros tag bs T1 T2 T3. apply Z.eqb_neq in T1, T2, T3. cbn [quotes pay_hi pay_ok]. rewrite T1, T2, T3. cbn [orb]. repeat split; reflexivity.
Qed.

Section WriteStringOk.
