Theorem write_string_ok : write_string_specU L HI.
Proof using APPEND_OK ESCAPE_OK FPM HIok LAY PUSHB_OK WBIGNUM_OK.
  intros tag sv bs Htag LBo cr sp r V S2 kx bx g. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & Ha0 & (Ha1 & Ha2 & Hsv) & Hinv & _ & Hroom & Himg & Hcred & Hobjs) Hcont.
  cbv beta in Hroom.
  assert (RM1 : tag = 1 -> g_len g + (2 + len bs) <= CLU) by (intros ->; rewrite dmax_raw in Hroom; exact Hroom).
  assert (RM23 : tag = 2 \/ tag = 3 -> g_len g + len bs <= CLU) by (intros T; rewrite (dmax_big tag bs T) in Hroom; exact Hroom).
  assert (RMO : tag <> 1 -> tag <> 2 -> tag <> 3 -> g_len g + (2 + esc_len bs) <= CLU)
    by (intros T1 T2 T3; destruct (dmax_esc tag bs T1 T2 T3) as (D & _ & _); rewrite D in Hroom; exact Hroom).
  pose proof (esc_len_bound bs) as ESCB.
  destruct Hsv as (q & Hq0 & Q0 & Hq8 & Hbq & Hdq & Hinb & Hap1 & Hap2 & (SV1 & SV2 & SV3)).
  destruct Hentry as (Hra & Hraok & Hsp & Htp & Hstk). destruct Hstk as (S1 & S2' & S3 & S4 & S5).
  unfold STRX_SCR, PMS.STR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK, ESC_SCR in *.
  assert (S2x : hl_sptop L - 2 ^ 23 + 8704 <= sp) by (clear - S2'; lia). clear S2'. rename S2x into S2'.
  pose proof Hobjs as ((OV1 & OV2 & OV3) & (OS1 & OS2 & OS3) & OAP). unfold ENC_SIZE, PML.apart in OV2, OAP, Hap1, Hap2.
  pose proof (PmLayout.ly_segs L LAY) as LS. pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof Hinv as (I1 & I2 & I3 & I4 & I5).
  set (n := len bs) in *. assert (N0 : 0 <= n) by (unfold n, len; lia).
  assert (GLB : incl (PML.srep_blocks (g_rep g)) (g_lbv g)) by (intros b Hb; unfold g_lbv; apply in_or_app; left; exact Hb).
  assert (SRCB : n = 0 \/ exists b, In b LBo /\ block_range L (fst b) (snd b) /\ fst b <= q /\ q + n <= fst b + snd b).
  { destruct Hinb as [Z0|(b & Hb & B1 & B2)]; [left; exact Z0|].
    destruct (EWB.other_block L HI HIok LBo (g_lbv g) cr M _ (g_rep g) b HH Hb GLB) as (_ & BR & _).
    right. exists b. split; [exact Hb|]. split; [exact BR|]. split; [exact B1 | exact B2]. }
  assert (N46 : n < 2 ^ 47 - 4096).
  { destruct SRCB as [Z0|(b & _ & (R0 & _ & _ & _ & R4) & B1 & B2)]; [lia | unfold hl_ceil in R4; lia]. }
  assert (DCOL : L5.defined M (V + 296) 8).
  { destruct I1 as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & X & _). exact X. }
  destruct (EAK.u64_of_defined M (V + 296) DCOL) as (col & Hcol0 & Hcol).
  pose proof I1 as (_ & H2 & _ & (fl & H4 & H4') & H5 & _). unfold O_SINK, O_FLAGS, O_BIGNUM_FMT in H2, H4, H5.
  destruct (flags16 M (V + 24) fl H4 H4') as (u & U0 & Hfl).
  set (E0 := Env (reg_ev R (fun v => Z_to_bv 64 (nth (v - 32) [S2; q; n; col; u] 0))) (fun _ => [])).
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; apply CL5.ev_reg).
  assert (V2 : ev E0 2 = Z_to_bv 64 sp) by (rewrite <- Hsp; exact (EV 2%bv)).
  assert (V4 : ev E0 4 = Z_to_bv 64 PML.TP) by (rewrite <- Htp; exact (EV 4%bv)).
  assert (V10 : ev E0 10 = Z_to_bv 64 V) by (rewrite <- Ha0; exact (EV 10%bv)).
  assert (V11 : ev E0 11 = Z_to_bv 64 sv) by (rewrite <- Ha1; exact (EV 11%bv)).
  assert (V12 : ev E0 12 = Z_to_bv 64 tag) by (rewrite <- Ha2; exact (EV 12%bv)).
  assert (V32 : ev E0 32 = Z_to_bv 64 S2) by reflexivity.
  assert (V33 : ev E0 33 = Z_to_bv 64 q) by reflexivity.
